// Clamp request + enforce context-only grounding. Reject prompt-injection vectors.
const body = ($input.first().json.body) || $input.first().json || {};
const q = typeof body.question === 'string' ? body.question : '';
const ctx = Array.isArray(body.context_lead_ids) ? body.context_lead_ids : [];
const session_id = typeof body.session_id === 'string' && /^[A-Za-z0-9._:-]{1,80}$/.test(body.session_id) ? body.session_id : null;
if (q.length < 3 || q.length > 2000 || /[\x00-\x1f\x7f]/.test(q)) throw new Error('ASK_REQUEST_REJECTED');
if (!ctx.every((x) => typeof x === 'string' && /^FAIR-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(x))) throw new Error('ASK_INVALID_CONTEXT');
return [{ json: { question: q, context_lead_ids: ctx.slice(0, 20), session_id } }];

// Keep only the leads from context_lead_ids, strip raw payloads, notes and PII beyond name/email.
const snapshot = $('Leads lesen').first().json.payload || {};
const wanted = new Set($('Eingabe prüfen').first().json.context_lead_ids);
const allowed = (snapshot.leads || []).filter((l) => wanted.has(l.lead_id)).map((l) => ({
  lead_id: l.lead_id,
  company: l.company,
  contact: l.contact,
  score_band: l.score_band,
  processing_status: l.processing_status,
  email_status: l.email_status,
  training_interest: l.training_interest,
  budget_status: l.budget_status,
  follow_up: l.follow_up,
  duplicate_status: l.duplicate_status
}));
return [{ json: { question: $('Eingabe prüfen').first().json.question, context: allowed } }];

